"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["63127"],{70242(e,t,a){a.r(t),a.d(t,{metadata:()=>r,default:()=>u,frontMatter:()=>d,contentTitle:()=>p,toc:()=>h,assets:()=>c});var r=JSON.parse('{"id":"hiecm/v3/api/m1/endpoints/m1-login-verify","title":"Verify a login OTP and get a user token","description":"Returns the user scoped token that profile calls need, sent afterwards as","source":"@site/docs/hiecm/v3/api/m1/endpoints/m1-login-verify.mdx","sourceDirName":"hiecm/v3/api/m1/endpoints","slug":"/hiecm/v3/api/m1/endpoints/m1-login-verify","permalink":"/docs/pr-9/docs/hiecm/v3/api/m1/endpoints/m1-login-verify","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1788936730000,"frontMatter":{"title":"Verify a login OTP and get a user token","sidebar_label":"Verify a login OTP and get a user token","sidebar_class_name":"api-method api-method--post","description":"Returns the user scoped token that profile calls need, sent afterwards as","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","verification":"unverified","source":"hiecm-m1.yaml","generated":true},"sidebar":"hiecm-v3-api","previous":{"title":"Choose which ABHA to sign in to","permalink":"/docs/pr-9/docs/hiecm/v3/api/m1/endpoints/m1-login-select-account"},"next":{"title":"Read the signed in person\'s ABHA profile","permalink":"/docs/pr-9/docs/hiecm/v3/api/m1/endpoints/m1-profile-get-account"}}'),n=a(62540),i=a(43023),s=a(70862),o=JSON.parse('{"id":"m1_login_verify","module":"M1 ABHA identity","moduleId":"m1","kind":"operation","method":"POST","path":"/v3/profile/login/verify","server":"https://abhasbx.abdm.gov.in/abha/api","servers":[{"url":"https://abhasbx.abdm.gov.in/abha/api","description":"ABHA Server, Sandbox (primary)"},{"url":"https://dev.abdm.gov.in/api/hiecm","description":"ABDM Gateway, Dev"}],"summary":"Verify a login OTP and get a user token","description":"Returns the user scoped token that profile calls need, sent afterwards as\\nthe `X-token` header. That token identifies one person, so it is not\\ninterchangeable with the gateway session token, which identifies your\\napplication.\\n\\nIf the identifier the person used maps to more than one ABHA, this\\nresponds with the list instead of a token, and you continue with the\\nuser selection call.\\n\\nDocumented responses cover 400, 401, 404 and 422 as well as 200, so\\nread the body rather than only the status.\\n","security":[{"name":"gatewaySession","type":"http","scheme":"bearer","description":"The `accessToken` from `POST /api/hiecm/gateway/v3/sessions`, which is described in hiecm-gateway.yaml. Send it as `Authorization: Bearer <ACCESS_TOKEN>`.\\n"},{"name":"bearerAuth","type":"http","scheme":"bearer","description":"JWT Bearer token from `POST /api/hiecm/gateway/v3/sessions`.\\nHeader: `Authorization: Bearer {accessToken}`\\n"},{"name":"xToken","type":"apiKey","description":"Short-lived session token returned in login/verify responses.\\nRequired for all `/profile/account/*` operations.\\nHeader: `X-Token: {token}`\\n"}],"headers":[{"name":"REQUEST-ID","required":true,"description":"Unique UUID v4 per request. Used for idempotency and distributed tracing.\\nGenerate a fresh UUID for every call.\\n","type":"string"},{"name":"TIMESTAMP","required":true,"description":"ISO 8601 UTC timestamp of the request.","type":"string"},{"name":"BENEFIT_NAME","required":false,"description":"The benefit scheme an enrolment belongs to. On enrolment and benefit calls, the value is `healthid api` on the enrol and search calls, and `healthid` on the login OTP and verify calls under Find ABHA and on some of the benefit calls. On the enrolment OTP request the header is present but explicitly disabled, so it is not sent there.\\n\\nThis header is spelled four different ways across requests: `BENEFIT_NAME` (most), `Benefit-Name` (demo auth and child ABHA calls), `BENEFIT-NAME` (child update, state district search) and `Benefit_Name` (once). Underscore and hyphen are different header names on the wire. Benefit programme calls also use scheme values beyond healthid: `COVIN` on an IRIS enrol and a profile photo update, and a disabled `PAN`.\\n\\nWhich spelling is correct has not been confirmed against the sandbox.\\n","example":"healthid api","type":"string"},{"name":"T-token","required":false,"description":"The transaction token that carries state between the two halves of a login. Returned by the verify call and sent back on the account selection call. Like X-token, the value carries a `Bearer ` prefix in every one of the recorded requests.","type":"string"},{"name":"X-token","required":false,"description":"The user scoped token returned when a person logs in or verifies an OTP. Profile calls act on one account, so they need this in addition to the gateway token. Required on the calls that read or change a specific person\'s account.\\n\\nThe value carries a `Bearer ` prefix, exactly like the Authorization header. Sending the bare token reads as an invalid token error.\\n","example":"Bearer <X_TOKEN_FROM_LOGIN_VERIFY>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"scope","type":"string[]","required":true,"description":"","encrypted":false},{"name":"authData","type":"object","required":true,"description":"","encrypted":false},{"name":"authData.authMethods","type":"string[]","required":true,"description":"","encrypted":false},{"name":"authData.otp","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.otp.txnId","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.otp.otpValue","type":"string","required":true,"description":"","encrypted":true},{"name":"authData.password","type":"object","required":false,"description":"","encrypted":true},{"name":"authData.password.ABHANumber","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.password.password","type":"string","required":true,"description":"","encrypted":true},{"name":"authData.face","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.face.txnId","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.bio","type":"object","required":false,"description":"","encrypted":false},{"name":"authData.bio.txnId","type":"string","required":true,"description":"","encrypted":false},{"name":"authData.bio.fingerPrintAuthPid","type":"string","required":true,"description":"","encrypted":false}],"requestExample":{"scope":["abha-login","mobile-verify"],"authData":{"authMethods":["otp"],"otp":{"txnId":"<TXN_ID>","otpValue":"<OTPVALUE>"}}},"responses":[{"status":"200","description":"Whether the login verified, with the user token and its expiry.","example":{"txnId":"<TXN_ID>","authResult":"success","message":"Aadhaar Face Authentication Success","token":"<TOKEN>","expiresIn":1800,"refreshToken":"<REFRESHTOKEN>","refreshExpiresIn":1296000,"accounts":[{"ABHANumber":"<ABHA_NUMBER>","preferredAbhaAddress":"<ABHA_ADDRESS>","name":"<NAME>","status":"ACTIVE","profilePhoto":"<BASE64_PHOTO>","mobileVerified":false}]}},{"status":"400","description":"The response.","example":{"faceDto":"Invalid Aadhaar face request","timestamp":"2025-01-15 13:29:43"}},{"status":"401","description":"The error returned, with its code and message.","example":{"code":"900901","message":"Invalid Credentials","description":"Invalid JWT token. Make sure you have provided the correct security credentials"}},{"status":"403","description":"Forbidden, the token is valid but not permitted for this operation","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}},{"status":"404","description":"The error returned, with its code and message.","example":{"code":"404","type":"Status report","message":"Runtime Error","description":"No matching resource found for given API Request"}},{"status":"422","description":"The error returned, with its code and message.","example":{"error":{"code":"ABDM-1204","message":"UIDAI Error code : 563 : Duplicate request (this error occurs when exactly same authentication request was re-sent by AUA)"}}},{"status":"500","description":"Server error, retry","example":{"code":"<CODE>","message":"<MESSAGE>","timestamp":"<TIMESTAMP>"}}],"tag":"ABHA verification, mobile OTP","tagDescription":"","curl":"curl --request POST \\\\\\n  --url https://abhasbx.abdm.gov.in/abha/api/v3/profile/login/verify \\\\\\n  --header \'REQUEST-ID: <REQUEST_ID>\' \\\\\\n  --header \'TIMESTAMP: <TIMESTAMP>\' \\\\\\n  --header \'BENEFIT_NAME: healthid api\' \\\\\\n  --header \'T-token: <T_TOKEN>\' \\\\\\n  --header \'X-token: Bearer <X_TOKEN_FROM_LOGIN_VERIFY>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"scope\\": [\\n    \\"abha-login\\",\\n    \\"mobile-verify\\"\\n  ],\\n  \\"authData\\": {\\n    \\"authMethods\\": [\\n      \\"otp\\"\\n    ],\\n    \\"otp\\": {\\n      \\"txnId\\": \\"<TXN_ID>\\",\\n      \\"otpValue\\": \\"<OTPVALUE>\\"\\n    }\\n  }\\n}\'"}');let d={title:"Verify a login OTP and get a user token",sidebar_label:"Verify a login OTP and get a user token",sidebar_class_name:"api-method api-method--post",description:"Returns the user scoped token that profile calls need, sent afterwards as",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",verification:"unverified",source:"hiecm-m1.yaml",generated:!0},p,c={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);